package com.example.csvfixtures.batch;
import static org.junit.jupiter.api.Assertions.*; import java.io.StringReader; import java.nio.file.Files; import java.nio.file.Path; import org.apache.commons.csv.CSVFormat; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.io.TempDir;
class FixtureRowTest {
    @Test void parsesFixture() throws Exception { var parser = CSVFormat.DEFAULT.parse(new StringReader("m1,17:00,Home,Away\n")); var row = FixtureRow.parse(parser.iterator().next(), "ES", "ACB"); assertEquals("m1", row.matchId()); assertEquals("ES", row.country()); assertEquals("Home", row.homeTeam()); assertEquals("17:00", row.eventTime().toString()); }
    @Test void parsesFixtureWithDatetimeWithoutShiftingTeamColumns(@TempDir Path directory) throws Exception { var path = directory.resolve("FIXTURES_20261016170201_europe_euroleague.csv"); Files.writeString(path, "match_id,event_time,home_team,away_team,event_datetime\nATu7NCdf,19:00,Besiktas,Bayern,2026-10-16T19:00:00+02:00\n"); try (var parser = CsvInput.open(path)) { var row = FixtureRow.parse(parser.iterator().next(), "europe", "euroleague"); assertEquals("Besiktas", row.homeTeam()); assertEquals("Bayern", row.awayTeam()); assertEquals("2026-10-16T19:00+02:00", row.eventDatetime().toString()); } }
    @Test void rejectsDatetimeInTeamColumn() throws Exception { var parser = CSVFormat.DEFAULT.parse(new StringReader("m1,19:00,Bayern,2026-10-16T19:00:00+02:00,2026-10-16T19:00:00+02:00\n")); var record = parser.iterator().next(); var error = assertThrows(IllegalArgumentException.class, () -> FixtureRow.parse(record, "europe", "euroleague")); assertTrue(error.getMessage().contains("field=away_team")); }
    @Test void rejectsMissingMatchId() throws Exception { var parser = CSVFormat.DEFAULT.parse(new StringReader(",17:00,Home,Away\n")); assertThrows(IllegalArgumentException.class, () -> FixtureRow.parse(parser.iterator().next(), "ES", "ACB")); }
}
